const $=s=>document.querySelector(s), chat=$('#chat');
const flow=['材料','机构','支付','出函'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" data-action="${action}">${label}</button>`;
const icon=(name)=>{const p={files:'<path d="M8 3h8l4 4v13H8Z M16 3v5h4 M4 7v14 M11 12h6 M11 16h4"/>',guide:'<path d="m4 5 5-2 6 2 5-2v16l-5 2-6-2-5 2Z M9 3v16 M15 5v16"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4Z"/><circle cx="12" cy="13" r="3"/>',wechat:'<path d="M20 11a7 7 0 0 1-8 7l-4 3v-4a7 7 0 1 1 12-6Z"/>',album:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1"/><path d="m4 18 5-5 3 3 3-4 5 6"/>'}[name]||p.spark;return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`};
const providers=[
 {name:'永诚财产保险股份有限公司',brand:'永诚保险',mark:'永诚',price:1000,time:'4–6小时',refund:'1个月内全额退',hours:'08:30–18:00',tags:['NEW','符合法院要求'],tone:'red'},
 {name:'大家财产保险有限责任公司',brand:'大家保险',mark:'大家',price:800,oldPrice:1000,time:'4–6小时',refund:'需扣费',hours:'08:30–18:00',tags:['该院办理过','最快30分钟','平台补贴'],tone:'orange',activity:true},
 {name:'紫金财产保险股份有限公司',brand:'紫金保险',mark:'ZKI',price:1000,time:'4–6小时',refund:'需扣费',hours:'08:30–18:00',tags:['该院办理过'],tone:'purple'},
 {name:'汇友相互保险社',brand:'汇友相互',mark:'汇友',price:1000,time:'2小时',refund:'1个月内全额退',hours:'06:30–22:00',tags:['该院办理过','最快30分钟'],tone:'teal'}
];
const fixture={court:'杭州市西湖区人民法院',preservationType:'财产保全',preservationCategory:'诉中保全',applicant:{name:'杭州青禾科技有限公司',id:'DEMO-企业证件-A',address:'杭州市西湖区示例路100号'},respondent:{name:'杭州远川贸易有限公司',id:'DEMO-企业证件-B'},thirdParty:null,cause:'买卖合同纠纷',amount:1000000,caseNo:'（2026）示例民初001号',factsReason:'申请人主张已按买卖合同交付货物，被申请人尚欠货款；为避免判决难以执行，申请对相应财产采取保全措施。',amountBasis:'依据合同价款、交付凭证及已付款记录，示例主张标的金额为1,000,000元。',targetRequirement:'请求查封、冻结被申请人名下价值不超过1,000,000元的财产。'};
let state,epoch=0,busy=false;
const docsFor=(kind)=>[{id:'application',name:kind==='arbitration'?'仲裁申请书.pdf':'财产保全申请书.pdf',type:'保全申请书',size:'2.1MB',mock:true,checked:true},{id:'complaint',name:'民事起诉状.pdf',type:'起诉状',size:'2.4MB',mock:true,checked:true},{id:'identity',name:'申请人营业执照.jpg',type:'申请人身份证明',size:'1.2MB',mock:true,checked:true},{id:'respondentProof',name:'被申请人身份材料.jpg',type:'被申请人身份材料',size:'1.1MB',mock:true,checked:true},{id:'courtNotice',name:'法院受理通知书.jpg',type:'法院受理通知书',size:'1.6MB',mock:true,checked:true}];
function reset(){epoch++;busy=false;state={step:0,docs:[],scenario:'',profile:'complete',uploadSource:'local',selectedProvider:null,paid:false,issued:false,downloaded:false,orderId:null,parsed:false,analysis:null};chat.innerHTML='';$('#uploadScreen').hidden=true;$('#providerDetailScreen').hidden=true;if($('#modal').open)$('#modal').close();$('#message').value='';$('#composer .send').disabled=false;renderSteps();renderOverview();assistant(`<div class="welcome-title">你好，我是<span>诉讼保</span><span class="hello-dot">。</span></div><div class="intro">有案件材料吗？我们从这里开始。</div><div class="paths"><div class="path-heading"><span>选择办理方式</span><small>01 — 02</small></div><button class="path" data-action="direct"><span class="path-icon">${icon('files')}</span><span><b>已有材料，直接办</b><small>上传材料 · 解析核对 · 选择机构</small></span><span class="arrow">→</span></button><button class="path" data-action="guide"><span class="path-icon">${icon('guide')}</span><span><b>首次申请，带我办</b><small>了解材料要求，按步骤完成申请</small></span><span class="arrow">→</span></button></div>`);chat.scrollTop=0}
function assistant(html){chat.insertAdjacentHTML('beforeend',`<div class="assistant"><div class="avatar">${icon('spark')}</div><div class="message-body"><div class="byline">诉讼保 · 申请助手</div>${html}</div></div>`);scroll()}
function user(text){chat.insertAdjacentHTML('beforeend',`<div class="user">${esc(text)}</div>`);scroll()}
function scroll(){chat.scrollTop=chat.scrollHeight}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function stream(text){const current=epoch;busy=true;$('#composer .send').disabled=true;const node=document.createElement('div');node.className='assistant';node.innerHTML=`<div class="avatar">${icon('spark')}</div><div class="message-body"><div class="byline">诉讼保 <span class="reply-status"><i></i>正在回复</span></div><div class="bubble streaming"></div></div>`;chat.append(node);const bubble=node.querySelector('.bubble');for(let i=0;i<text.length;i+=4){if(current!==epoch)return false;bubble.textContent=text.slice(0,i+4);scroll();await wait(15)}bubble.className='bubble';node.querySelector('.byline').textContent='诉讼保 · 申请助手';busy=false;$('#composer .send').disabled=false;return true}
function renderSteps(){const labels=['材料','机构','支付','出函'];$('#steps').innerHTML=labels.map((v,i)=>`<div class="step ${state.step===i?'current':i<state.step||state.downloaded?'done':''}" aria-label="第${i+1}步：${v}"><span>${i<state.step||state.downloaded?'✓':i+1}</span>${v}</div>`).join('')}
function renderOverview(){const status=state.downloaded?'保函已下载':state.issued?'保函可下载':state.paid?'等待出函':state.selectedProvider!==null?'待支付':state.parsed?state.analysis?.ok?'待选择机构':'待处理材料':'待上传材料';$('#miniProgress').textContent=status;$('#draft').textContent=status;$('#ratio').textContent=`${state.docs.length} 项` ;$('#fileCount').textContent=state.docs.length;$('#checklist').innerHTML=state.docs.map(d=>`<div class="check ready"><span class="check-icon">✓</span>${esc(d.type||d.name)}</div>`).join('');$('#caseInfo').innerHTML=state.analysis?.info?`<div class="info-row"><span>法院</span><b>${esc(state.analysis.info.court)}</b></div><div class="info-row"><span>申请人</span><b>${esc(state.analysis.info.applicant.name)}</b></div>`:'<div class="info-row"><span>等待材料解析</span></div>'}
function openUpload(clear=false){if(clear){state.docs=[];state.parsed=false;state.analysis=null;state.scenario='';state.selectedProvider=null;state.step=0;epoch++;renderSteps();renderOverview()}$('#modal').close();$('#uploadScreen').hidden=false;renderUpload()}
function renderUpload(){const tabs=[['local','本地'],['album','相册'],['wechat','微信'],['scan','扫描']];$('#uploadTabs').innerHTML=tabs.map(([id,n])=>`<button type="button" class="${state.uploadSource===id?'selected':''}" data-action="source-${id}">${n}</button>`).join('')+'<button type="button" class="upload-close" data-action="close-upload" aria-label="关闭">×</button>';const count=state.docs.length;$('#uploadHint').innerHTML=count?`<div class="upload-list-title"><div><b>材料列表 (${count})</b><span>演示模式 · 文件仅留在此页面</span></div><button type="button" data-action="pick-source">＋ 添加材料</button></div>${state.scenario==='partial'?`<div class="upload-add-missing"><b>补充缺少材料</b>${!state.docs.some(d=>d.id==='application')?btn('示例保全申请书','add-demo-application'):''}${!state.docs.some(d=>d.id==='identity')?btn('示例申请人身份证明','add-demo-identity'):''}</div>`:''}`:`<div class="upload-empty"><span class="upload-empty-icon">${icon('files')}</span><b>请上传案件材料</b><p>起诉状、保全申请书、身份证明等。支持图片、Word、PDF。</p><button type="button" data-action="pick-source">＋ 添加材料</button></div><div class="upload-demo"><span>快速体验交互</span>${btn('材料齐全','demo-complete')}${btn('材料不齐','demo-partial')}${btn('信息冲突','demo-conflict')}</div>`;$('#uploadFiles').innerHTML=state.docs.map((d,i)=>`<div class="upload-file"><label><input type="checkbox" data-file-check="${i}" ${d.checked?'checked':''} aria-label="选择${esc(d.name)}"><span class="file-type">${/\.pdf$/i.test(d.name)?'PDF':/\.docx?$/i.test(d.name)?'W':'图'}</span><span class="file-detail"><b>${esc(d.name)}</b><small>${esc(d.size||'本地文件')} · ${esc(d.type||'待分类')}</small></span></label><button type="button" data-action="remove-${i}" aria-label="移除${esc(d.name)}">×</button></div>`).join('');const selected=state.docs.filter(d=>d.checked).length;$('#selectAll').checked=count>0&&selected===count;$('#uploadSelection').textContent=`已选 ${selected}/${count}`;$('#uploadConfirm').disabled=selected===0;$('#uploadConfirm').textContent=selected?'上传并解析':'上传解析'}
function sourcePick(){if(state.uploadSource==='album')return $('#albumInput').click();if(state.uploadSource==='scan')return $('#scanInput').click();if(state.uploadSource==='wechat')return showModal('<h2>从微信选择</h2><p>网页演示无法直接读取微信聊天文件。请先将文件保存到手机，再从本地选择。</p><div class="actions">'+btn('选择已保存的文件','pick-local',true)+btn('取消','close')+'</div>');$('#fileInput').click()}
function addFiles(files,source){for(const f of files){if(f.size>20*1024*1024){showModal('<h2>文件过大</h2><p>每份文件请控制在 20 MB 以内。</p>');continue}state.docs.push({id:'local-'+Date.now()+'-'+Math.random(),name:f.name,size:(f.size/1024/1024).toFixed(1)+'MB',type:source==='scan'?'扫描件':'待分类',mock:false,checked:true})}state.scenario='local';renderUpload()}
function addDemo(scenario){state.scenario=scenario;state.docs=docsFor();if(scenario==='partial')state.docs=state.docs.filter(d=>!['application','identity'].includes(d.id));if(scenario==='conflict')state.docs=state.docs.filter(d=>d.id!=='courtNotice');renderUpload()}
function showModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function currentFixture(){const data=structuredClone(fixture);const complaint={court:fixture.court,plaintiffs:[{name:fixture.applicant.name,id:fixture.applicant.id}],defendants:[{name:fixture.respondent.name,id:fixture.respondent.id}],factsReason:fixture.factsReason,amountBasis:fixture.amountBasis};const application={court:fixture.court,applicant:{...fixture.applicant},respondent:{...fixture.respondent},preservationCategory:fixture.preservationCategory,amount:fixture.amount,targetRequirement:fixture.targetRequirement};if(state.scenario==='conflict'){application.court='杭州市上城区人民法院';application.applicant.id='DEMO-企业证件-X';application.respondent.name='杭州远舟贸易有限公司'}return {data,complaint,application,applicantId:fixture.applicant.id,respondentId:fixture.respondent.id}}
function validate(){if(state.scenario==='local'||state.docs.some(d=>!d.mock))return {ok:false,mode:'unavailable',issues:['本地文件尚未接入真实识别服务，无法提取内容或校验一致性。'],info:null};const ids=new Set(state.docs.map(d=>d.id));const required=[['application','保全申请书'],['complaint','起诉状'],['identity','申请人身份证明']];const missing=required.filter(([id])=>!ids.has(id)).map(([,label])=>label);const {data,complaint,application,applicantId,respondentId}=currentFixture();if(missing.length){const partial={court:ids.has('complaint')?complaint.court:null,preservationType:null,preservationCategory:null,applicant:ids.has('complaint')?{name:complaint.plaintiffs[0]?.name,id:complaint.plaintiffs[0]?.id,address:null}:null,respondent:ids.has('complaint')?{name:complaint.defendants[0]?.name,id:complaint.defendants[0]?.id}:null,thirdParty:null,cause:ids.has('complaint')?data.cause:null,amount:ids.has('complaint')?data.amount:null,caseNo:ids.has('complaint')?data.caseNo:null,factsReason:ids.has('complaint')?complaint.factsReason:null,amountBasis:ids.has('complaint')?complaint.amountBasis:null,targetRequirement:null,partial:true};return {ok:false,mode:'missing',missing,issues:[],info:partial}}const issues=[];if(application.preservationCategory!=='仲裁保全'&&complaint.court!==application.court)issues.push('法院不一致：起诉状与保全申请书所载法院不同，待确认。');if(!complaint.plaintiffs.some(p=>p.name===application.applicant.name))issues.push('申请人不一致：保全申请书申请人未包含在起诉状原告中，待确认。');if(complaint.plaintiffs.find(p=>p.name===application.applicant.name)?.id!==application.applicant.id||application.applicant.id!==applicantId)issues.push('申请人证件号码不一致：起诉状、保全申请书与身份证明需一致，待确认。');if(!complaint.defendants.some(p=>p.name===application.respondent.name))issues.push('被申请人不一致：保全申请书被申请人未包含在起诉状被告中，待确认。');if(complaint.defendants.find(p=>p.name===application.respondent.name)?.id!==application.respondent.id||application.respondent.id!==respondentId)issues.push('被申请人证件号码不一致：起诉状、保全申请书与身份证明需一致，待确认。');return {ok:issues.length===0,mode:issues.length?'conflict':'complete',missing:[],issues,info:data}}
async function analyze(){const selected=state.docs.filter(d=>d.checked);if(!selected.length)return;state.docs=selected.map(d=>({...d,checked:true}));state.parsed=false;state.analysis=null;const token=epoch;$('#uploadProgress').hidden=false;$('#uploadProgressName').textContent=selected[0].name;$('#uploadProgressCount').textContent=`1 / ${selected.length} 已完成`;for(const n of [12,39,68,100]){if(token!==epoch)return;$('#uploadPercent').textContent=`${n}%`;$('#uploadProgressBar').style.width=`${n}%`;await wait(150)}$('#uploadProgress').hidden=true;$('#uploadScreen').hidden=true;user(`添加 ${selected.length} 份材料`);const stages=['文件上传成功','文件解压与安全校验','识别案件材料类型','智能提取案件信息','生成解析结果'];assistant(`<div class="parse-card"><div class="parse-head"><span class="parse-icon">${icon('files')}</span><div><b>材料解析中</b><small>${esc(selected.map(d=>d.name).slice(0,2).join('、'))}${selected.length>2?' 等':''}</small></div></div><div class="parse-progress"><i></i></div><ol>${stages.map((s,i)=>`<li data-parse-stage="${i}"><span>○</span>${s}</li>`).join('')}</ol><small>演示解析进度，文件内容未上传至服务器</small></div>`);const card=chat.lastElementChild.querySelector('.parse-card');for(let i=0;i<stages.length;i++){if(token!==epoch)return;const li=card.querySelector(`[data-parse-stage="${i}"]`);li.classList.add('active');li.querySelector('span').textContent='◌';card.querySelector('.parse-progress i').style.width=`${Math.round((i+1)/stages.length*100)}%`;scroll();await wait(430);li.classList.remove('active');li.classList.add('done');li.querySelector('span').textContent='✓'}if(token!==epoch)return;const result=validate();state.analysis=result;state.parsed=true;renderOverview();renderResult()}
function resultFields(info){if(!info)return '';const shown=v=>v===null||v===undefined||v===''?'未提取':v;const person=p=>p?[p.name,p.id,p.address].filter(Boolean).join(' / '):'未提取';const lines=[['法院名称',shown(info.court)],['保全类型',shown(info.preservationType)],['保全类别',shown(info.preservationCategory)],['申请人',person(info.applicant)],['被申请人',person(info.respondent)],['第三方 / 案外人',info.partial?'未提取':info.thirdParty?person(info.thirdParty):'无（非必填）'],['案由',shown(info.cause)],['标的金额',info.amount===null?'未提取':`¥ ${info.amount.toLocaleString('zh-CN')}`],['案号',info.partial?'待补充材料核对':info.caseNo||'未提供（非必填）']];return `<div class="result-section"><h4>案件信息</h4>${lines.map(([k,v])=>`<div class="result-line"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div><div class="result-section"><h4>事实与理由 <small>来源：${info.partial?'起诉状':'起诉状、保全申请书'}</small></h4><p>${esc(shown(info.factsReason))}</p></div><div class="result-section"><h4>标的金额依据 <small>来源：${info.partial?'起诉状':'起诉状、保全申请书'}</small></h4><p>${esc(shown(info.amountBasis))}</p></div><div class="result-section"><h4>保全标的要求 <small>来源：保全申请书</small></h4><p>${esc(shown(info.targetRequirement))}</p></div>`}
function renderResult(){const r=state.analysis;if(!r)return;let head=r.ok?'材料完整 · 关键信息一致':r.mode==='missing'?'还需补充材料':r.mode==='conflict'?'信息不一致 · 待确认':'本地材料待接入识别';const issues=r.issues?.length?`<div class="result-issues">${r.issues.map(s=>`<p>! ${esc(s)}</p>`).join('')}</div>`:'';const missing=r.missing?.length?`<div class="result-issues">缺少：${r.missing.map(esc).join('、')}</div>`:'';const details=r.info?`<details class="case-details" ${r.ok?'open':''}><summary>查看解析结果与字段来源</summary>${resultFields(r.info)}</details>`:'';const actions=r.ok?btn('确认信息并选择机构','confirm',true)+btn('查看完整解析','result'):r.mode==='missing'?btn('补充缺少材料','supplement',true)+btn('制作起诉状','template-complaint')+btn('制作保全申请书','template-application'):r.mode==='conflict'?btn('重新上传整套材料','reupload-all',true):btn('使用示例材料体验解析','reupload-all',true);assistant(`<div class="card result-card ${r.ok?'is-ok':'is-alert'}"><span class="tag">${r.ok?'解析完成':'需处理'}</span><h3>${head}</h3><p class="muted">${r.mode==='unavailable'?'网页 Demo 尚未连接 OCR。':'示例材料为模拟解析结果，核对信息仅供查看。'}</p>${missing}${issues}${details}<div class="actions">${actions}</div></div>`)}
function showProviders(){if(!state.analysis?.ok)return renderResult();state.step=1;renderSteps();renderOverview();user('确认信息并选择机构');assistant(`<div class="bubble provider-intro">已为您匹配以下机构，可自主选择合适的机构继续申请保函。<small>以下报价、时效与规则均为演示数据。</small></div>${providers.map((p,i)=>`<article class="provider-card"><button type="button" class="provider-card-main" data-action="provider-detail-${i}" aria-label="查看${p.brand}详情"><div class="provider-card-head"><div class="provider-logo ${p.tone}"><b>${p.mark}</b><small>${p.brand}</small></div><div class="provider-price"><b>¥${p.price.toFixed(2)}</b>${p.oldPrice?`<del>¥${p.oldPrice.toFixed(2)}</del>`:''}<small>保函费</small></div></div><div class="provider-name">${p.name}</div><div class="provider-tags">${p.tags.map(t=>`<span class="${t==='NEW'?'new':t==='平台补贴'?'subsidy':''}">${t}</span>`).join('')}</div><div class="provider-bottom"><div><b>${p.time}</b><small>出函时效</small></div><div><b>${p.refund}</b><small>退保规则</small></div><div><b>${p.hours}</b><small>受理时间</small></div><span class="provider-arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="m9 5 7 7-7 7"/></svg></span></div><div class="provider-view">查看收费标准、退保规则与机构介绍 <span>查看详情 ›</span></div></button></article>`).join('')}`)}
function providerTabContent(p,tab){if(tab==='refund')return `<div class="detail-copy"><h3>退保规则</h3><p>当前展示的退保标签为 <b>${esc(p.refund)}</b>。</p><p>实际可退金额、期限及所需材料，以承办机构出具的正式规则和订单约定为准。</p><div class="detail-note">演示说明：本页面不会生成真实订单或收取费用。</div></div>`;if(tab==='about')return `<div class="detail-copy"><h3>机构介绍</h3><p><b>${esc(p.name)}</b></p><p>当前演示页展示该机构在本申请场景中的预计出函时效、受理时间及保函费。正式申请前，请以机构提供的资质、服务范围和业务说明为准。</p><div class="detail-note">机构名称用于卡片交互示例，其余业务信息均为演示数据。</div></div>`;if(tab==='sample')return `<div class="detail-copy"><h3>保函样例</h3><div class="sample-paper"><b>诉讼保 · 保函样例</b><p>示例文件，仅用于展示出函样式。</p><div></div><div></div><div class="short"></div><small>正式保函由承办机构审核后出具</small></div></div>`;return `<div class="detail-copy"><h3>收费说明</h3><p>· 保函费仅为出具保函的费用，不包含面签费、笔录费、邮寄费等。</p><p>· 关于其他费用：如法院要求面签、笔录或邮寄，相关费用以实际发生及机构正式说明为准。</p><div class="detail-fee-note">当前演示保函费 <b>¥${p.price.toFixed(2)}</b></div>${p.oldPrice?`<p class="detail-discount">展示优惠：原价 ¥${p.oldPrice.toFixed(2)}，示例优惠价 ¥${p.price.toFixed(2)}。</p>`:''}</div>`}
function renderProviderDetail(i,tab='fee'){const p=providers[i];if(!p)return;state.detailProvider=i;state.detailTab=tab;$('#providerDetailScreen').hidden=false;$('#providerDetailContent').innerHTML=`<div class="detail-hero"><div class="provider-logo ${p.tone}"><b>${p.mark}</b><small>${p.brand}</small></div><h2>${p.name}</h2><div class="detail-metrics"><div><b>工作日${p.hours}</b><small>受理时间</small></div><div><b>${p.time}</b><small>出函时效</small></div><div><b class="detail-refund-tag">${p.refund}</b><small>退保</small></div></div><div class="detail-price">保函费 <b>¥${p.price.toFixed(2)}</b></div></div><div class="detail-tabs" role="tablist" aria-label="机构信息">${[['fee','收费说明'],['refund','退保规则'],['about','机构介绍'],['sample','保函样例']].map(([id,label])=>`<button type="button" role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="detail-tab-${id}">${label}</button>`).join('')}</div><div class="detail-pane" id="providerDetailPane">${providerTabContent(p,tab)}</div>`;$('#providerDetailChoose').dataset.action=`provider-${i}`;$('#providerDetailContent').scrollTop=0}
function switchProviderTab(tab){const p=providers[state.detailProvider];if(!p)return;state.detailTab=tab;document.querySelectorAll('.detail-tabs button').forEach(b=>{const selected=b.dataset.action===`detail-tab-${tab}`;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected))});$('#providerDetailPane').innerHTML=providerTabContent(p,tab)}
function chooseProvider(i){state.selectedProvider=i;state.step=2;renderSteps();renderOverview();const p=providers[i];user(`选择${p.brand}`);showModal(`<h2>确认支付</h2><div class="payment-amount">¥ ${p.price.toFixed(2)}</div><p class="muted">${p.name}<br>出函时效：${p.time} · 受理时间：${p.hours}</p><label class="pay-consent"><input type="checkbox" id="payAgree"> 我了解这是模拟支付，不会发生扣款</label><p id="payError" class="error"></p><div class="actions">${btn('确认模拟支付','pay-confirm',true)}${btn('返回选择机构','close')}</div>`)}
function orderCard(){if(state.selectedProvider===null)return;const p=providers[state.selectedProvider];assistant(`<div class="card order-card"><span class="tag">${state.issued?'已出函':state.paid?'等待出函':'待支付'}</span><h3>订单详情</h3><div class="order-line"><span>订单号</span><b>${esc(state.orderId||'待生成')}</b></div><div class="order-line"><span>承办机构</span><b>${p.name}</b></div><div class="order-line"><span>演示保函费</span><b>¥${p.price.toFixed(2)}</b></div><div class="order-line"><span>出函时效</span><b>${p.time}</b></div><div class="actions">${state.issued?btn('下载示例保函','download',true):state.paid?btn('模拟出函完成','issue',true):btn('去模拟支付','pay',true)}</div></div>`)}
async function act(action){if(action==='close'){if($('#modal').open)$('#modal').close();return}if(action==='close-upload'){$('#uploadScreen').hidden=true;return}if(action==='reset')return showModal(`<h2>发起新申请？</h2><p>当前演示记录会清空。</p><div class="actions">${btn('确认新建','reset-confirm',true)}${btn('继续当前申请','close')}</div>`);if(action==='reset-confirm')return reset();if(action==='direct')return openUpload();if(action==='guide'){user('首次申请，请带我办');if(!await stream('先准备起诉状、保全申请书和申请人身份证明。可以上传已有材料，也可以下载空白草稿在本地制作。'))return;return assistant(`<div class="actions">${btn('上传已有材料','upload',true)}${btn('制作起诉状','template-complaint')}${btn('制作保全申请书','template-application')}</div>`)}if(action==='upload'||action==='materials')return openUpload();if(action.startsWith('source-')){state.uploadSource=action.slice(7);renderUpload();return}if(action==='pick-source')return sourcePick();if(action==='pick-local'){$('#modal').close();return $('#fileInput').click()}if(action.startsWith('demo-'))return addDemo(action.slice(5));if(action.startsWith('add-demo-')){const id=action.slice(9);const doc=docsFor().find(d=>d.id===id);if(doc&&!state.docs.some(d=>d.id===id))state.docs.push(doc);renderUpload();return}if(action.startsWith('remove-')){state.docs.splice(Number(action.slice(7)),1);renderUpload();return}if(action==='analyze')return analyze();if(action==='result')return showModal(`<h2>材料解析结果</h2><span class="tag">只读 · 模拟解析</span>${resultFields(state.analysis?.info)}<div class="actions">${btn('关闭','close')}</div>`);if(action==='overview')return state.analysis?.info?act('result'):showModal('<h2>当前申请</h2><p>上传材料后可查看解析结果与校验状态。</p>');if(action==='supplement'){openUpload();return}if(action==='reupload-all')return openUpload(true);if(action.startsWith('template-')){const type=action==='template-complaint'?'起诉状':'保全申请书';return showModal(`<h2>本地制作${type}</h2><p>下载空白草稿，填写并核实后再作为材料上传。本 Demo 不会把草稿直接写入解析结果。</p><div class="actions">${btn('下载空白草稿','download-template-'+type,true)}${btn('返回','close')}</div>`)}if(action.startsWith('download-template-')){const type=action.slice('download-template-'.length);const blob=new Blob([`${type}（空白演示草稿）\n\n法院名称：________\n申请人：________\n被申请人：________\n案由：________\n标的金额：________\n事实与理由：________\n\n请核实并按实际要求签章。`],{type:'text/plain;charset=utf-8'});downloadBlob(blob,`${type}-空白演示草稿.txt`);return}if(action==='confirm')return showProviders();if(action==='close-detail'){$('#providerDetailScreen').hidden=true;return}if(action.startsWith('provider-detail-'))return renderProviderDetail(Number(action.slice(16)));if(action.startsWith('detail-tab-'))return switchProviderTab(action.slice(11));if(action.startsWith('provider-')){$('#providerDetailScreen').hidden=true;return chooseProvider(Number(action.slice(9)))}if(action.startsWith('activity-'))return showModal('<h2>活动详情</h2><p>该卡片的优惠价与补贴标签仅用于展示交互，不代表实际机构报价。</p><div class="actions">'+btn('知道了','close',true)+'</div>');if(action==='pay')return chooseProvider(state.selectedProvider);if(action==='pay-confirm'){if(!$('#payAgree').checked){$('#payError').textContent='请先确认这是模拟支付。';return}state.paid=true;state.step=3;state.orderId='DEMO-'+Date.now().toString().slice(-10);$('#modal').close();renderSteps();renderOverview();user('完成模拟支付');if(await stream('模拟支付成功。订单进入等待出函状态；出函后可下载示例文件。'))orderCard();return}if(action==='issue'){state.issued=true;renderOverview();assistant('<div class="bubble">示例保函已生成，可在订单中下载。</div>');orderCard();return}if(action==='download'){const p=providers[state.selectedProvider];const html=`<!doctype html><meta charset="utf-8"><title>示例保函</title><h1>诉讼保 · 示例保函</h1><p>演示样本，无法律效力</p><p>订单号：${esc(state.orderId)}</p><p>承办机构：${esc(p.name)}</p><p>标的金额：¥${fixture.amount.toLocaleString()}</p>`;downloadBlob(new Blob([html],{type:'text/html;charset=utf-8'}),`${state.orderId}-示例保函.html`);state.downloaded=true;renderSteps();assistant('<div class="success">✓ 已发起示例保函下载。文件无实际保函效力。</div>');return}if(action==='progress')return showModal(`<h2>办理进度</h2><p>当前阶段：${flow[state.step]}</p><p>已选材料：${state.docs.length} 项</p><div class="actions">${btn('关闭','close')}</div>`);if(action==='requirements')return showModal('<h2>材料要求</h2><p>财产保全演示：保全申请书、起诉状、申请人身份证明。自然人需身份证正反面，企业需营业执照；诉中保全建议提供法院受理通知书。</p><div class="actions">'+btn('去上传','upload',true)+'</div>');if(action==='menu')return showModal(`<h2>更多功能</h2><div class="sheet-options">${btn('上传材料','upload')}${btn('查看进度','progress')}${btn('材料要求','requirements')}${btn('发起新申请','reset')}</div>`);if(action==='exit')return act('reset')}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target)act(target.dataset.action)});
document.addEventListener('change',e=>{if(e.target.matches('[data-file-check]')){state.docs[Number(e.target.dataset.fileCheck)].checked=e.target.checked;renderUpload()}if(e.target.id==='selectAll'){state.docs.forEach(d=>d.checked=e.target.checked);renderUpload()}});
for(const [id,source]of [['fileInput','local'],['albumInput','album'],['scanInput','scan']])$('#'+id).addEventListener('change',e=>{addFiles([...e.target.files],source);e.target.value='' });
$('#composer').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const text=$('#message').value.trim();if(!text)return;$('#message').value='';user(text);if(/材料|上传|文件/.test(text))return act('upload');if(/机构/.test(text)&&state.analysis?.ok)return act('confirm');if(/支付/.test(text)&&state.selectedProvider!==null)return act('pay');if(/进度|订单/.test(text))return state.paid?orderCard():act('progress');if(/首次|不会|怎么/.test(text))return act('guide');if(await stream('我可以带你上传材料、查看解析结果、选择机构和跟进订单。'))assistant(`<div class="actions">${btn('上传材料','upload',true)}${btn('查看材料要求','requirements')}</div>`)});
reset();
